Copy the workbook, read cached values from Worksheet1, and keep the header plus rows whose column B value starts with H or A (case-insensitive). Write the compacted rows back into A1:J10411 and clear the remaining answer-region cells. Save the result to OUT.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

SHEET = "Worksheet1"
MAX_ROW = 10411
MAX_COL = 10

vws = vals[SHEET]
ws = wb[SHEET]

def clean_value(v):
    if isinstance(v, str):
        v = v.strip()
        if v == "":
            return None
    return v

def starts_with_h_or_a(v):
    if v is None:
        return False
    if isinstance(v, str):
        s = v.strip()
    else:
        s = str(v).strip()
    return bool(s) and s[0].upper() in ("H", "A")

kept = []
for r, row in enumerate(
    vws.iter_rows(min_row=1, max_row=MAX_ROW, min_col=1, max_col=MAX_COL, values_only=True),
    start=1
):
    row = list(row)
    if r == 1 or starts_with_h_or_a(row[1]):
        kept.append([clean_value(x) for x in row])

for i, row in enumerate(kept, start=1):
    for j, val in enumerate(row, start=1):
        ws.cell(row=i, column=j).value = val

if len(kept) < MAX_ROW:
    for row in ws.iter_rows(min_row=len(kept) + 1, max_row=MAX_ROW, min_col=1, max_col=MAX_COL):
        for cell in row:
            cell.value = None

wb.save(OUT)

print("kept_rows", len(kept))
if len(kept) > 1:
    print("first_data", kept[1][:3])
if len(kept) > 2:
    print("second_data", kept[2][:3])
